"""Camera and proprioception-only controller for the recorded CandleCleanup episode."""
import os,sys,json,time
import numpy as np
from PIL import Image,ImageDraw
from scipy.spatial.transform import Rotation as R
from scipy.optimize import least_squares
from rcb_client import Robot
ROOT='/app/output'
r=Robot(); spec=r.spec()
def save(o,label):
    p=f'{ROOT}/{label}';o.save(p)
    open(f'{ROOT}/latest','w').write(p)
    imgs=[]
    for c,im in o.last.items():
        im=Image.fromarray(im).resize((640,480));ImageDraw.Draw(im).text((10,10),c,fill='yellow');imgs.append(im)
    montage=Image.new('RGB',(1280,960))
    for i,im in enumerate(imgs):montage.paste(im,((i%2)*640,(i//2)*480))
    montage.save(f'{ROOT}/view.jpg')
    print('Saved',label,'time_left',o.meta['time_left_s'],'proprio',np.round(o.meta['proprio']['now'][:13],4),'eef',np.round(o.meta['proprio']['now'][26:29],4))
    return o

def obs():return r.get_obs(include_depth=True,video='none')
def run(A,label='motion'):
    A=np.array(A);stamp=str(int(time.time()*1000))+'_'+label
    np.save(f'{ROOT}/{stamp}_actions.npy',A)
    return save(r.submit('joint_position',A,include_depth=True,video='none'),stamp)
def current():return np.array(obs().meta['proprio']['now'])
def joints(q,seconds=2,grip=None):
    p=current();a=p[29:42].copy();a[8:12]=0;a[12]=-1
    if grip is not None:a[7]=grip
    n=int(seconds/.05);A=np.tile(a,(n+10,1));A[:n,:7]=np.linspace(p[4:11],q,n);A[n:,:7]=q
    return run(A,'joints')
def fk(q):
    T=np.eye(4)
    for qi,xyz,rx in zip(q,[(0,0,.333),(0,0,0),(0,-.316,0),(.0825,0,0),(-.0825,.384,0),(0,0,0),(.088,0,0)],[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2]):
        M=np.eye(4);M[:3,:3]=R.from_euler('x',rx).as_matrix()@R.from_euler('z',qi).as_matrix();M[:3,3]=xyz;T=T@M
    return T

def point(label,cam,u,v):
    m=json.load(open(label+'/meta.json'));c=m['cameras']['robot0_'+cam];d=np.load(label+'/depth_robot0_'+cam+'.npy').squeeze();z=float(d[v,u]);K=np.array(c['intrinsic_cv']);T=np.array(c['cam2world_gl']);p=T@np.array([(u-K[0,2])*z/K[0,0],-(v-K[1,2])*z/K[1,1],-z,1]);print(u,v,z,p[:3]);return p[:3]
if __name__=='__main__':
    cmd=sys.argv[1] if len(sys.argv)>1 else 'obs'
    if cmd=='obs':save(obs(),str(int(time.time()*1000))+'_obs')
    elif cmd=='joints':joints(json.loads(sys.argv[2]),float(sys.argv[3]) if len(sys.argv)>3 else 2,float(sys.argv[4]) if len(sys.argv)>4 else None)
    elif cmd=='point':point(open(ROOT+'/latest').read(),sys.argv[2],int(sys.argv[3]),int(sys.argv[4]))
PY
